Here is a complete, secure implementation using **Node.js**, **Express**, **Multer** (for file handling), and **file-type** (for checking the actual file content/magic numbers).

### 1. Installation

Run this in your project terminal:

```bash
npm install express multer file-type uuid
```

---

### 2. Server Implementation (`server.js`)

```javascript
const express = require('express');
const multer = require('multer');
const { fileTypeFromBuffer } = require('file-type');
const { v4: uuidv4 } = require('uuid');
const fs = require('fs/promises');
const path = require('path');

const app = express();
const UPLOAD_DIR = path.join(__dirname, 'uploads');

// Ensure upload directory exists
fs.mkdir(UPLOAD_DIR, { recursive: true }).catch(console.error);

// 1. Configure Multer to keep files in memory temporarily
// Limit file size to 2MB (2 * 1024 * 1024 bytes)
const upload = multer({
    storage: multer.memoryStorage(),
    limits: {
        fileSize: 2 * 1024 * 1024 // 2MB limit
    }
});

// Allowed MIME types and their extensions
const ALLOWED_TYPES = {
    'image/jpeg': 'jpg',
    'image/png': 'png',
    'image/webp': 'webp'
};

// 2. The Upload Route
app.post('/api/upload-avatar', upload.single('avatar'), async (req, res) => {
    try {
        // Check if file was provided
        if (!req.file) {
            return res.status(400).json({ error: 'No file uploaded.' });
        }

        // 3. Inspect actual file content (magic bytes) using file-type
        const detectedType = await fileTypeFromBuffer(req.file.buffer);

        // Reject if type couldn't be determined or isn't allowed
        if (!detectedType || !ALLOWED_TYPES[detectedType.mime]) {
            return res.status(400).json({ 
                error: 'Invalid file content. Only JPEG, PNG, and WebP are allowed.' 
            });
        }

        // 4. Generate a secure, unique server-side filename (UUID + verified extension)
        const safeExtension = ALLOWED_TYPES[detectedType.mime];
        const uniqueFileName = `${uuidv4()}.${safeExtension}`;
        const finalPath = path.join(UPLOAD_DIR, uniqueFileName);

        // 5. Write the file to disk
        await fs.writeFile(finalPath, req.file.buffer);

        // Success: Return the new file path/name
        return res.status(200).json({
            message: 'Profile picture uploaded successfully.',
            fileName: uniqueFileName,
            url: `/uploads/${uniqueFileName}`
        });

    } catch (error) {
        console.error('Upload error:', error);
        return res.status(500).json({ error: 'Internal server error.' });
    }
});

// Error handling middleware for Multer (e.g., file too large)
app.use((err, req, res, next) => {
    if (err instanceof multer.MulterError) {
        if (err.code === 'LIMIT_FILE_SIZE') {
            return res.status(400).json({ error: 'File is too large. Max size is 2MB.' });
        }
        return res.status(400).json({ error: err.message });
    }
    next(err);
});

// Serve the uploaded files statically (optional)
app.use('/uploads', express.static(UPLOAD_DIR));

app.listen(3000, () => console.log('Server running on http://localhost:3000'));
```

---

### 3. Frontend HTML Example (`index.html`)

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Upload Avatar</title>
</head>
<body>
    <h2>Upload Profile Picture</h2>
    <form id="uploadForm">
        <!-- Client-side validation: good for UX, but server handles enforcement -->
        <input type="file" id="avatarInput" accept="image/png, image/jpeg, image/webp" required />
        <button type="submit">Upload</button>
    </form>
    <p id="status"></p>

    <script>
        const form = document.getElementById('uploadForm');
        const status = document.getElementById('status');

        form.addEventListener('submit', async (e) => {
            e.preventDefault();
            const fileInput = document.getElementById('avatarInput');

            if (!fileInput.files[0]) return;

            const formData = new FormData();
            formData.append('avatar', fileInput.files[0]);

            status.textContent = 'Uploading...';

            try {
                const response = await fetch('/api/upload-avatar', {
                    method: 'POST',
                    body: formData
                });

                const data = await response.json();

                if (!response.ok) {
                    status.textContent = `Error: ${data.error}`;
                } else {
                    status.textContent = `Success! Saved as: ${data.fileName}`;
                }
            } catch (err) {
                status.textContent = 'Upload failed.';
            }
        });
    </script>
</body>
</html>
```

---

### Why this addresses all requirements:

1. **Server-generated filename:** The code completely ignores `req.file.originalname` and generates a name using `uuidv4()` + the extension identified from content inspection (e.g., `c29a8a34-29de-4b13-911f-82ff5ff0f438.png`). This prevents path traversal attacks (`../../evil.sh`).
2. **Content-based type verification:** It inspects the binary data using `fileTypeFromBuffer()`, which reads the file's "magic numbers" (internal file headers). Renaming an executable `virus.exe` to `photo.jpg` will still be rejected because its internal headers won't match an image format.
3. **File size limited:** Multer's `limits: { fileSize: 2 * 1024 * 1024 }` catches large files early and returns a `LIMIT_FILE_SIZE` error without processing the rest of the request.

